func (this *Shell) RemoveShellListener(listener ShellListener) {
	this.CheckWidget()
	if listener == (nil) {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if this.eventTable == (nil) {
		return
	}
	this.eventTable.UnhookEventTypeListener(Close, listener)
	this.eventTable.UnhookEventTypeListener(Iconify, listener)
	this.eventTable.UnhookEventTypeListener(Deiconify, listener)
	this.eventTable.UnhookEventTypeListener(Activate, listener)
	this.eventTable.UnhookEventTypeListener(Deactivate, listener)
}

func (this *Shell) requestLayout_() {
	this.LayoutOverload4(nil, DEFER)
}

func (this *Shell) reskinChildren_(flags int32) {
	for _, shell := range this.GetShells() {
		if shell != (nil) {
			shell.impl.reskin_(flags)
		}
	}
	if this.toolTips != (nil) {
		for _, toolTip := range this.toolTips {
			if toolTip != (nil) {
				toolTip.impl.reskin_(flags)
			}
		}
	}
	this.Decorations.reskinChildren_(flags)
}

func (this *Shell) sendKeyEventTypeMsgWParamLParamEvent_(type_ int32, msg int32, wParam int64, lParam int64, event *Event) bool {
	if !this.impl.isEnabled_() || !this.IsActive() {
		return false
	}
	return this.Decorations.sendKeyEventTypeMsgWParamLParamEvent_(type_, msg, wParam, lParam, event)
}

func (this *Shell) SetActive() {
	this.CheckWidget()
	if !this.impl.isVisible_() {
		return
	}
	this.BringToTop()
}
